// FSP Pages Generator - creates 15 new pick pages by cloning an existing page's exact structure
// Run from the freesportspicks folder:  node gen_fsp_pages.js
const fs = require('fs');
const path = require('path');
const BASE = 'C:\\Users\\randy\\Downloads\\freesportspicks';
const PICKS = path.join(BASE, 'picks');
const DOMAIN = 'https://www.freesportspicks.pro';

// read an existing page as the structural template (inherits GA, CSS, header, footer, exit-CTA)
const TPL = fs.readFileSync(path.join(PICKS, 'nfl-picks', 'index.html'), 'utf8');

// slice out the reusable header (everything from <body> up to <main ...>) and footer (from </main> to </html>)
const bodyStart = TPL.indexOf('<body>');
const mainOpen = TPL.indexOf('<main');
const mainClose = TPL.indexOf('</main>');
if (bodyStart < 0 || mainOpen < 0 || mainClose < 0) { console.error('Template anchors not found'); process.exit(1); }
const HEADER = TPL.substring(bodyStart + 6, mainOpen);        // between <body> and <main
const FOOTER = TPL.substring(mainClose + 7);                  // after </main>  (includes footer, CTA, </body></html>)
// grab the <main ...> opening tag attributes
const mainTagEnd = TPL.indexOf('>', mainOpen);
const MAIN_OPEN_TAG = TPL.substring(mainOpen, mainTagEnd + 1);

function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

function buildHead(p){
  const url = DOMAIN + '/picks/' + p.slug + '/';
  const webpage = JSON.stringify({"@context":"https://schema.org","@type":"WebPage","name":p.metatitle,"description":p.desc,"url":url,"publisher":{"@type":"Organization","name":"FreeSportsPicks.pro","url":DOMAIN,"logo":{"@type":"ImageObject","url":DOMAIN+"/fsp-logo.svg"}}});
  const faqSchema = JSON.stringify({"@context":"https://schema.org","@type":"FAQPage","mainEntity":p.faqs.map(f=>({"@type":"Question","name":f[0],"acceptedAnswer":{"@type":"Answer","text":f[1]}}))});
  return `<!DOCTYPE html>
<html lang="en">
<head>
<link rel="icon" type="image/svg+xml" href="/favicon.svg">
<link rel="shortcut icon" href="/favicon.svg">
<!-- Google tag (gtag.js) -->
<script async src="https://www.googletagmanager.com/gtag/js?id=G-YZPX14DK4Y"></script>
<script>
  window.dataLayer = window.dataLayer || [];
  function gtag(){dataLayer.push(arguments);}
  gtag('js', new Date());
  gtag('config', 'G-YZPX14DK4Y');
</script>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${p.metatitle}</title>
<meta name="description" content="${p.desc.replace(/"/g,'&quot;')}">
<link rel="canonical" href="${url}">
<meta property="og:type" content="website">
<meta property="og:url" content="${url}">
<meta property="og:title" content="${p.metatitle}">
<meta property="og:description" content="${p.desc.replace(/"/g,'&quot;')}">
<meta property="og:image" content="${DOMAIN}/images/og-home.jpg">
<meta property="og:site_name" content="FreeSportsPicks.pro">
<meta name="twitter:card" content="summary_large_image">
<link rel="stylesheet" href="/css/main.css">
<script type="application/ld+json">
${webpage}
</script>
<script type="application/ld+json">
${faqSchema}
</script>
</head>
<body>`;
}

function buildMain(p){
  const relatedHtml = p.related.map(r=>`      <li><a href="${r[0]}">${r[1]}</a></li>`).join('\n');
  const faqHtml = p.faqs.map(f=>`      <div style="border-bottom:1px solid rgba(0,0,0,.08);padding:18px 0"><h3 style="font-size:18px;margin:0 0 8px">${esc(f[0])}</h3><p style="margin:0;line-height:1.7">${esc(f[1])}</p></div>`).join('\n');
  return `${MAIN_OPEN_TAG}
  <div class="container">
    <div class="breadcrumb"><a href="/">Home</a> <span>/</span> <a href="/picks/">Picks</a> <span>/</span> <span>${esc(p.crumb)}</span></div>
    <div class="article-hero">
      <span class="article-badge">${esc(p.badge)}</span>
      <h1>${esc(p.h1)}</h1>
      <div class="article-meta">
        <div class="meta-avatar">FSP</div>
        <div><div class="meta-name">FreeSportsPicks.pro Experts</div><div class="meta-date">Updated Daily &middot; 2026 Season</div></div>
      </div>
    </div>
${p.body}
    <h2 style="font-size:24px;margin:36px 0 14px;padding-bottom:8px;border-bottom:2px solid rgba(0,0,0,.08)">Frequently Asked Questions</h2>
${faqHtml}
    <h2 style="font-size:24px;margin:36px 0 14px;padding-bottom:8px;border-bottom:2px solid rgba(0,0,0,.08)">More Free Picks</h2>
    <ul style="columns:2;line-height:2">
${relatedHtml}
    </ul>
  </div>
</main>`;
}

